<template><q-page class="q-pa-lg"><div class="text-h4 q-mb-lg">Zaliha</div><q-table :rows="items" :columns="columns" row-key="id_zaliha" :loading="loading"><template #body-cell-kolicina="p"><q-td :props="p">{{p.value}} {{p.row.jedinica_mjere||''}}</q-td></template><template #body-cell-akcije="p"><q-td :props="p"><q-btn flat icon="add" @click="change(p.row,1)"/><q-btn flat icon="remove" @click="change(p.row,-1)"/></q-td></template></q-table></q-page></template>
<script setup>
import {onMounted,ref} from 'vue';import {useQuasar} from 'quasar';import {api} from 'boot/axios';const $q=useQuasar();const items=ref([]);const loading=ref(false);const columns=[{name:'proizvod_naziv',label:'Proizvod',field:'proizvod_naziv',align:'left'},{name:'sifra',label:'Šifra',field:'sifra'},{name:'kolicina',label:'Količina',field:'kolicina'},{name:'minimalna_kolicina',label:'Minimum',field:'minimalna_kolicina'},{name:'lokacija_skladista',label:'Lokacija',field:'lokacija_skladista'},{name:'akcije',label:'Akcije',field:'id_zaliha'}];async function load(){loading.value=true;try{items.value=(await api.get('/zaliha')).data;}finally{loading.value=false;}}async function change(row,sign){const amount=prompt('Količina:', '1');if(amount===null)return;const n=Number(amount);if(!Number.isFinite(n)||n<=0)return;$q.loading.show();try{await api.post(`/zaliha/${row.id_zaliha}/${sign>0?'dodaj':'umanji'}`,{kolicina:n});await load();}catch(e){$q.notify({type:'negative',message:e.response?.data?.message||'Promjena zalihe nije uspjela.'});}finally{$q.loading.hide();}}onMounted(load);
</script>
